exec(open('/home/claude/work/devim/dmc.py').read())
C=12
SRC=['ebhiḥ stavaiśca māṁ nityaṁ stoṣyate yaḥ samāhitaḥ | / tasyāhaṁ sakalāṁ bādhāṁ śamayiṣyāmyasaṁśayam || 2||',
'madhukaiṭabhanāśaṁ ca mahiṣāsuraghātanam | / kīrtayiṣyanti ye tadvadvadhaṁ śumbhaniśumbhayoḥ || 3||',
'aṣṭamyāṁ ca caturdaśyāṁ navamyāṁ caikacetasaḥ | / śroṣyanti caiva ye bhaktyā mama māhātmyamuttamam || 4||',
'na teṣāṁ duṣkṛtaṁ kiñcidduṣkṛtotthā na cāpadaḥ | / bhaviṣyati na dāridryaṁ na caiveṣṭaviyojanam || 5||',
'śatrubhyo na bhayaṁ tasya dasyuto vā na rājataḥ | / na śastrānalatoyaughāt kadācit sambhaviṣyati || 6||',
'tasmānmamaitanmāhātmyaṁ paṭhitavyaṁ samāhitaiḥ | / śrotavyaṁ ca sadā bhaktyā paraṁ svastyayanaṁ mahat || 7||',
'upasargānaśeṣāṁstu mahāmārīsamudbhavān | / tathā trividhamutpātaṁ māhātmyaṁ śamayenmama || 8||',
'yatraitatpaṭhyate samyaṅnityamāyatane mama | / sadā na tadvimokṣyāmi sānnidhyaṁ tatra me sthitam || 9||',
'jānatājānatā vāpi balipūjāṁ yathā kṛtām | / pratīkṣiṣyāmyahaṁ prītyā vahnihomaṁ tathākṛtam || 11||',
'śaratkāle mahāpūjā kriyate yā ca vārṣikī | / tasyāṁ mamaitanmāhātmyaṁ śrutvā bhaktisamanvitaḥ || 12|| / sarvābādhāvinirmukto dhanadhānyasamanvitaḥ | / manuṣyo matprasādena bhaviṣyati na saṁśayaḥ || 13||',
'śrutvā mamaitanmāhātmyaṁ tathā cotpattayaḥ śubhāḥ | / parākramaṁ ca yuddheṣu jāyate nirbhayaḥ pumān || 14||',
'ripavaḥ saṅkṣayaṁ yānti kalyāṇaṁ copapadyate | / nandate ca kulaṁ puṁsāṁ māhātmyaṁ mama śṛṇvatām || 15||',
'śāntikarmaṇi sarvatra tathā duḥsvapnadarśane | / grahapīḍāsu cogrāsu māhātmyaṁ śṛṇuyānmama || 16||',
'upasargāḥ śamaṁ yānti grahapīḍāśca dāruṇāḥ | / duḥsvapnaṁ ca nṛbhirdṛṣṭaṁ susvapnamupajāyate || 17||',
'bālagrahābhibhūtānāṁ bālānāṁ śāntikārakam | / saṅghātabhede ca nṛṇāṁ maitrīkaraṇamuttamam || 18||',
'paśupuṣpārghyadhūpaiśca gandhadīpaistathottamaiḥ | / viprāṇāṁ bhojanairhomaiḥ prokṣaṇīyairaharniśam ||21|| / anyaiśca vividhairbhogaiḥ pradānairvatsareṇa yā | / prītirme kriyate sāsmin sakṛduccarite śrute ||22||',
'śrutaṁ harati pāpāni tathārogyaṁ prayacchati | / rakṣāṁ karoti bhūtebhyo janmanāṁ kīrtanaṁ mama || 23||',
'yuṣmābhiḥ stutayo yāśca yāśca brahmarṣibhiḥ kṛtāḥ| / brahmaṇā ca kṛtāstāstu prayacchantu śubhāṁ matim || 25||',
'araṇye prāntare vāpi dāvāgniparivāritaḥ| / dasyubhirvā vṛtaḥ śūnye gṛhīto vāpi śatrubhiḥ || 26||',
'siṁhavyāghrānuyāto vā vane vā vanahastibhiḥ | / rājñā kruddhena cājñapto vadhyo bandhagato’pi vā || 27||',
'āghūrṇito vā vātena sthitaḥ pote mahārṇave | / patatsu cāpi śastreṣu saṅgrāme bhṛśadāruṇe || 28||',
'sarvābādhāsu ghorāsu vedanābhyardito’pi vā || 29|| / smaran mamaitaccaritaṁ naro mucyeta saṅkaṭāt | / mama prabhāvātsiṁhādyā dasyavo vairiṇastathā | / dūrādeva palāyante smarataścaritaṁ mama || 30||',
'ityuktvā sā bhagavatī caṇḍikā caṇḍavikramā| / paśyatāṁ sarvadevānāṁ tatraivāntaradhīyata || 32||',
'te’pi devā nirātaṅkāḥ svādhikārānyathā purā | / yajñabhāgabhujaḥ sarve cakrurvinihatārayaḥ || 33||',
'evaṁ bhagavatī devī sā nityāpi punaḥ punaḥ | / sambhūya kurute bhūpa jagataḥ paripālanam || 36||',
'tayaitanmohyate viśvaṁ saiva viśvaṁ prasūyate | / sā yācitā ca vijñānaṁ tuṣṭā ṛddhiṁ prayacchati || 37||',
'vyāptaṁ tayaitatsakalaṁ brahmāṇḍaṁ manujeśvara | / mahādevyā mahākālī mahāmārīsvarūpayā || 38||',
'saiva kāle mahāmārī saiva sṛṣṭirbhavatyajā | / sthitiṁ karoti bhūtānāṁ saiva kāle sanātanī || 39||',
'bhavakāle nṛṇāṁ saiva lakṣmīrvṛddhipradā gṛhe | / saivābhāve tathā’lakṣmīrvināśāyopajāyate || 40||',
'stutā sampūjitā puṣpairgandhadhūpādibhistathā | / dadāti vittaṁ putrāṁśca matiṁ dharme tathā śubhām || 41||']
def num(s): return re.findall(r'\|\|\s*(\d+)\s*\|\|',s)
FV=[dict(n=('–'.join([num(s)[0],num(s)[-1]]) if len(num(s))>1 else num(s)[0]),lines=L(s)) for s in SRC]
def S(*ns): return ' / '.join(s for s in SRC if any(x in num(s) for x in ns))
BOOK=lambda x,y,s=1: f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2"><path d="M-30 0 q15 -8 30 0 q15 -8 30 0 v36 q-15 -8 -30 0 q-15 -8 -30 0z" fill="#fff3b0"/><path d="M0 0 v36"/></g>'
READER=lambda x,y,s=1: person(x,y,'#ff8c1a','#c98b5a',s)+BOOK(x,y-40*s,.6*s)
HY='THE DEVĪ SPEAKS'
V=[
VP(C,'2–3',S('2','3'),'WHOEVER PRAISES ME',
 sc('The Goddess speaking from a glow above a person reciting from a book; scenes of her three victories in small circles',GLOW(110,40,40)+DEVI(110,0,.5,False)+READER(110,150,.9)+''.join(f'<circle cx="{40+k*70}" cy="110" r="18" fill="#fff8ec" stroke="#111"/>' for k in range(3))+T(40,114,'I',12)+T(110,114,'II',12)+T(180,114,'III',12)),
 'The Devī said: “Whoever, with a collected mind, praises me constantly with these hymns, I will without doubt quell every trouble of his. And those who sing of the slaying of Madhu and Kaiṭabha, the killing of Mahiṣāsura, and likewise the slaying of Śumbha and Niśumbha…”',
 [('samāhitaḥ','<b>with a collected mind</b>'),('sakalām bādhām','<b>every trouble</b>'),('śamayiṣyāmi','<b>I will quell</b>'),('asaṃśayam','<b>without doubt</b>'),('kīrtayiṣyanti','<b>will sing of</b>')],
 '<b>The Goddess speaks for herself.</b> After eleven chapters of being praised, the Devī now tells what reading her story does. Chapter 12 is called the <b>phalaśruti</b>, “the hearing of the fruits”. She names all three stories, the three caritas, as one.',
 'The Devī herself <b>promises to quell every trouble</b>.'),
VP(C,'4–6',S('4','5','6'),'THE EIGHTH, NINTH AND FOURTEENTH',
 sc('A calendar strip of moon phases with the 8th, 9th and 14th days glowing, a family listening to the recitation',''.join(f'<circle cx="{12+k*14}" cy="30" r="5" fill="{"#ffd60a" if k in (7,8,13) else "#fff"}" stroke="#111"/>' for k in range(15))+T(110,54,'8 · 9 · 14',12,'#c0392b')+READER(70,150,.8)+person(130,150,'#e05a8a','#c98b5a',.6)+person(160,150,'#2a9d6f','#c98b5a',.5)),
 '“…and those who, with one-pointed mind and devotion, hear this supreme glory of mine on the eighth, the fourteenth and the ninth days: to them no evil will come, nor calamities born of evil deeds, nor poverty, nor separation from loved ones. They will have no fear from enemies, from robbers or from kings, nor ever from weapons, fire or floods.”',
 [('aṣṭamī · navamī · caturdaśī','<b>the 8th, 9th and 14th lunar days</b>'),('eka-cetasaḥ','<b>one-pointed</b>'),('dāridrya','<b>poverty</b>'),('iṣṭa-viyojana','<b>separation from loved ones</b>'),('śastra-anala-toya','<b>weapons, fire, water</b>')],
 '<b>Why Aṣṭamī and Navamī.</b> These lunar days are already sacred to the Goddess; in Navarātri, Durgā Aṣṭamī and Mahānavamī are the high points. This verse is one reason the Devī Māhātmya is read on exactly those days.',
 'Read on <b>Aṣṭamī and Navamī</b>, it protects from every fear.'),
VP(C,'7–9',S('7','8','9'),'“I WILL NEVER LEAVE THAT PLACE”',
 sc('A small shrine where the text is read daily, the Goddess’s glow settled inside it permanently; disease clouds turning away outside',
  '<rect x="60" y="60" width="100" height="80" fill="#fff3b0" stroke="#111" stroke-width="2"/><path d="M50 62 L110 20 L170 62z" fill="#c0392b" stroke="#111" stroke-width="2"/>'+GLOW(110,100,30)+DEVI(110,64,.25,False)+READER(80,140,.4)+'<ellipse cx="20" cy="40" rx="18" ry="10" fill="#777"/><ellipse cx="200" cy="40" rx="18" ry="10" fill="#777"/><path d="M36 40 l-10 -6 M184 40 l10 -6" stroke="#111"/>'),
 '“So this glory of mine should be read with a collected mind, and always heard with devotion: it is the supreme, great way to well-being. My glory will quell all calamities arising from great epidemics, and the threefold portents. The place, my shrine, where this is properly read every day, I will never leave; my presence remains there.”',
 [('svasti-ayana','<b>the way to well-being</b>'),('mahā-mārī','<b>great epidemic</b>'),('trividham utpātam','<b>the threefold portents</b>: on earth, in the sky, in the heavens'),('āyatana','<b>shrine, home</b>'),('sānnidhya','<b>presence</b>')],
 '<b>Her presence stays.</b> The most loved promise of the chapter: where her story is read daily, she never leaves. That is why many homes and temples read the Devī Māhātmya every day. Note too the specific mention of epidemics (mahāmārī).',
 'Where her story is read, <b>she stays</b>.'),
VP(C,'11–13',S('11','12'),'IN AUTUMN, THE GREAT WORSHIP',
 sc('An autumn Durga Puja: the Goddess on her lion in a decorated pandal, devotees with lamps and drums, a full harvest of grain',
  '<rect width="220" height="160" fill="#fff3d0"/><path d="M30 130 V40 h160 V130" fill="#fde4e4" stroke="#111" stroke-width="2"/><path d="M24 42 Q110 -6 196 42" fill="#c0392b" stroke="#111" stroke-width="2"/>'+DEVI(110,30,.45)+LION(110,116,.4)+person(20,156,'#ff8c1a','#c98b5a',.5)+person(200,156,'#2a9d6f','#c98b5a',.5)+''.join(f'<path d="M{50+k*12} 156 v-14" stroke="#e0a800" stroke-width="3"/>' for k in range(4))),
 '“Whether done knowingly or unknowingly, I will accept with love the worship and offerings made, and the fire-offering too. And at the great annual worship performed in the autumn season, the person who hears this glory of mine with devotion will, by my grace, be freed from all troubles and blessed with wealth and grain; of this there is no doubt.”',
 [('jānatā ajānatā','<b>knowingly or unknowingly</b>'),('prītyā','<b>with love</b>'),('śarat-kāla','<b>autumn</b>'),('mahā-pūjā vārṣikī','<b>the great annual worship</b>'),('dhana-dhānya','<b>wealth and grain</b>')],
 '<b>Śarad Navarātri.</b> The “great annual worship in autumn” is the root of Durgā Pūjā and the autumn Navarātri, when this text is read across India. And the kindest line: worship done <i>without knowing</i> the rules is accepted with love too.',
 'Even worship done <b>without knowing the rules</b> is accepted with love.'),
VP(C,'14–15',S('14','15'),'FEARLESSNESS',
 sc('A person standing tall and unafraid, shadows of enemies fading, a family smiling behind them',GLOW(80,70,40)+person(80,150,'#ff8c1a','#c98b5a',1.1)+''.join(f'<g opacity="{.6-k*.15:.2f}">'+ASURA(150+k*20,150,.5)+'</g>' for k in range(3))+person(40,150,'#e05a8a','#c98b5a',.5)),
 '“Hearing this glory of mine, and my auspicious births, and my valour in battles, a person becomes fearless. Enemies perish, welfare comes, and the families of those who hear my glory rejoice.”',
 [('utpattayaḥ śubhāḥ','<b>auspicious births</b>: her appearances'),('parākrama','<b>valour</b>'),('nirbhayaḥ','<b>fearless</b>'),('kalyāṇam','<b>welfare</b>'),('nandate kulam','<b>the family rejoices</b>')],
 '<b>The real fruit.</b> Of all the promises, this one explains the rest: the hearer becomes <i>nirbhaya</i>, fearless. The stories of her three victories are meant to change the reader’s heart, as they changed King Suratha’s.',
 'The deepest fruit is <b>fearlessness</b>.'),
VP(C,'16–18',S('16','17','18'),'BAD DREAMS AND QUARRELS',
 sc('A sleeper whose dark dream cloud turns into a bright one; two people who had turned away now shaking hands; a child sleeping peacefully',NIGHTSKY+'<ellipse cx="60" cy="40" rx="40" ry="18" fill="#555"/><path d="M100 40 h14" stroke="#fff" stroke-width="2"/><ellipse cx="160" cy="40" rx="40" ry="18" fill="#ffd60a" opacity=".7"/>'+person(70,150,'#ff8c1a','#c98b5a',.6)+person(110,150,'#2a9d6f','#c98b5a',.6)+'<path d="M80 120 h20" stroke="#f2c79b" stroke-width="5"/>'+'<rect x="150" y="130" width="50" height="16" rx="6" fill="#fff" stroke="#111"/><circle cx="160" cy="130" r="6" fill="#f2c79b" stroke="#111"/>'),
 '“In all rites for peace, when bad dreams are seen, and in severe troubles from the planets, one should hear my glory. Calamities are calmed, and the cruel troubles of the planets; the bad dream people have seen turns into a good dream. It brings peace to children seized by childhood ailments, and is the best means of making friendship among people when there is a rift.”',
 [('śānti-karman','<b>rites for peace</b>'),('duḥsvapna','<b>bad dream</b>'),('graha-pīḍā','<b>trouble from planets</b>'),('bāla-graha','<b>childhood afflictions</b>'),('saṅghāta-bheda','<b>a rift among people</b>'),('maitrī-karaṇam','<b>making friendship</b>')],
 '<b>Ordinary life.</b> These verses are about everyday worries: nightmares, sick children, quarrels in a family or a group. The Devī Māhātmya was always a household text as much as a temple one.',
 'It turns bad dreams good, and <b>quarrels into friendship</b>.'),
VP(C,'21–23',S('21','23'),'ONE READING = A YEAR OF WORSHIP',
 sc('One side of a scale piled with a year of offerings, flowers, lamps, incense, feasts; the other side a single book, and the scale balanced',
  '<path d="M110 30 v100" stroke="#111" stroke-width="3"/><path d="M40 50 h140" stroke="#111" stroke-width="3"/><path d="M40 50 l-20 50 h40z M180 50 l-20 50 h40z" fill="none" stroke="#111"/>'+''.join(f'<text x="{30+k*8}" y="{96-(k%2)*8}" font-size="10">{e}</text>' for k,e in enumerate('🌸🪔🌸🍚🪔🌼'))+BOOK(180,84,.6)+'<path d="M80 140 h60" stroke="#111" stroke-width="4"/>'),
 '“The love I feel when worshipped for a whole year with animals, flowers, offerings, incense, perfumes and the finest lamps, with feeding of brāhmaṇas, with fire-offerings, with sprinklings day and night, and with many other enjoyments and gifts: that love is mine when this is recited or heard just once. Heard, the telling of my births takes away sins, gives health, and protects from evil beings.”',
 [('vatsareṇa','<b>over a year</b>'),('sakṛt','<b>just once</b>'),('uccarite śrute','<b>recited or heard</b>'),('ārogyam','<b>health</b>'),('rakṣā','<b>protection</b>')],
 '<b>A bold claim.</b> A single heartfelt reading pleases her as much as a whole year of elaborate ritual. The text puts listening with devotion above expensive offerings.',
 'One devoted reading pleases her <b>like a year of rituals</b>.'),
VP(C,'25',S('25'),'MAY THE HYMNS GIVE A GOOD MIND',
 sc('Three small figures, the gods, the sages and Brahma, each holding a scroll of their hymn, light flowing from the scrolls into a person’s head',GODS(70,.4,1,40,0)+SAGE(110,70,.6)+BRAHMA(180,50,.4)+''.join(f'<path d="M{x} 80 L110 120" stroke="#ffd60a" stroke-width="2" stroke-dasharray="3 3"/>' for x in (40,110,180))+person(110,156,'#ff8c1a','#c98b5a',.6)+GLOW(110,116,10)),
 '“The hymns sung by you, the hymns made by the brahmarṣis, and those made by Brahmā: may they grant an auspicious mind.”',
 [('yuṣmābhiḥ','<b>by you</b>, the gods'),('stutayaḥ','<b>hymns</b>'),('brahma-ṛṣibhiḥ','<b>by the great sages</b>'),('śubhām matim','<b>an auspicious mind</b>')],
 '<b>The three hymns.</b> She means Brahmā’s hymn (chapter 1, Part 6), the gods’ hymns (chapters 4, 5 and 11), and the sages’ praises. Their fruit is not things but <i>śubhā mati</i>, a good mind.',
 'The hymns’ best gift is <b>a good mind</b>.'),
VP(C,'26–28',S('26','27','28'),'IN EVERY DANGER',
 sc('Four dangers in small panels: a forest fire, a lion and tiger in the jungle, a prisoner before an angry king, a boat in a storm at sea',
  ''.join(f'<rect x="{4+(k%2)*108}" y="{4+(k//2)*78}" width="104" height="74" fill="{bg}" stroke="#111"/>' for k,bg in enumerate(['#ffe3c4','#e7f4ea','#fff3b0','#dfe9f6']))
  +FIRE(56,50,.6)+LION(150,50,.4)+'<ellipse cx="190" cy="56" rx="12" ry="6" fill="#ff8c1a" stroke="#111"/>'+KING(40,140,.5)+person(80,150,'#888','#c98b5a',.4)+'<path d="M112 120 q27 -10 54 0 t50 0" fill="none" stroke="#2a6ab0" stroke-width="3"/><path d="M146 118 h36 l-6 10 h-24z" fill="#c9a26b" stroke="#111"/>'),
 '“In a forest or a lonely place, surrounded by forest fire; surrounded by robbers in a deserted spot or seized by enemies; pursued by lions and tigers, or by wild elephants in the forest; condemned to death by an angry king, or in prison; tossed by the wind in a boat on the great ocean; or where weapons fall in the fiercest battle…”',
 [('dāva-agni','<b>forest fire</b>'),('dasyu','<b>robbers</b>'),('vana-hastin','<b>wild elephant</b>'),('vadhyaḥ bandha-gataḥ','<b>condemned or in prison</b>'),('pote mahā-arṇave','<b>in a boat on the great ocean</b>')],
 '<b>A list of real fears.</b> These are the dangers of an ancient traveller, soldier or prisoner. The list builds up to one promise on the next page.',
 'Fire, beasts, kings, storms, war: <b>every danger is listed</b>.'),
VP(C,'29–30',S('29'),'“REMEMBER MY STORY”',
 sc('A person in the dark, eyes closed, remembering; lions and robbers running away at a distance as the Goddess’s light surrounds them',NIGHTSKY+GLOW(110,90,44)+person(110,150,'#ff8c1a','#c98b5a',.9)+'<ellipse cx="110" cy="40" rx="40" ry="18" fill="#fff" stroke="#111"/>'+DEVI(110,20,.18,False)+LION(30,140,.4)+ASURA(196,150,.4)+'<path d="M10 140 h-6 M214 150 h6" stroke="#fff" stroke-width="2"/>'),
 '“…in all terrible troubles, or tormented by pain: remembering this story of mine, a person is freed from the crisis. By my power, lions and others, robbers and enemies flee far away from one who remembers my story.”',
 [('vedanā-abhyarditaḥ','<b>tormented by pain</b>'),('smaran','<b>remembering</b>'),('mucyeta saṅkaṭāt','<b>is freed from crisis</b>'),('dūrāt eva palāyante','<b>flee from afar</b>')],
 '<b>Remembering is enough.</b> Not reading, not ritual: in a crisis, just <i>remembering</i> her story frees us. It is the same boon the gods received in chapter 4: “whenever we remember you, end our dangers.”',
 'In a crisis, just <b>remember her story</b>.'),
VP(C,'32–33',S('32','33'),'SHE VANISHES; HEAVEN IS RESTORED',
 sc('The Goddess fading into light while the gods return to their thrones and receive their sacrificial shares again',GLOW(110,40,40)+'<g opacity=".4">'+DEVI(110,0,.5,False)+'</g>'+FIRE(110,130,.6)+GODS(150,.45,4,30,50)),
 'The sage said: Having said this, the blessed Caṇḍikā of fierce valour vanished right there, as all the gods watched. And the gods, their enemies slain, free from fear, resumed their offices as before and all enjoyed their shares of sacrifice.',
 [('caṇḍa-vikramā','<b>of fierce valour</b>'),('antaradhīyata','<b>vanished</b>'),('nirātaṅkāḥ','<b>free from fear</b>'),('sva-adhikārān','<b>their own offices</b>'),('yajña-bhāga','<b>shares of sacrifice</b>')],
 '<b>Order restored.</b> Everything taken by Śumbha in chapter 5 (the Sun’s office, the Moon’s, Kubera’s, the shares of sacrifice) returns to its rightful holder. The surviving asuras go down to Pātāla (12.34–35).',
 'She vanishes, and <b>everything returns to its place</b>.'),
VP(C,'36–37',S('36','37'),'ETERNAL, YET SHE COMES AGAIN',
 sc('The Goddess at the centre of a great wheel of ages, appearing again and again at points around its rim',GLOW(110,80,30)+DEVI(110,50,.3,False)+'<circle cx="110" cy="80" r="64" fill="none" stroke="#111" stroke-width="2"/>'+''.join(DEVI(110+64*math.cos(k*1.047),80+64*math.sin(k*1.047)-14,.16,False) for k in range(6))),
 'Thus, O king, the blessed Devī, though eternal, comes into being again and again and protects the world. By her this universe is deluded; she gives birth to the universe; when prayed to, she grants wisdom, and when pleased, prosperity.',
 [('nityā api','<b>though eternal</b>'),('punaḥ punaḥ sambhūya','<b>coming into being again and again</b>'),('mohyate','<b>is deluded</b>'),('prasūyate','<b>is born</b>'),('vijñānam · ṛddhim','<b>wisdom · prosperity</b>')],
 '<b>Medhas sums up.</b> Back in the frame, the sage turns to the king. She is eternal, so she was never born; yet she “comes into being again and again”. Her appearances are for the world, not because she needs them.',
 'Eternal, <b>yet she comes again and again</b>.'),
VP(C,'38–41',S('38','39','40','41'),'MAHĀMĀRĪ AND LAKṢMĪ',
 sc('Two halves: a dark Mahakali spreading over the cosmos at the end of time, and a bright Lakshmi blessing a prosperous home',
  '<rect x="0" y="0" width="110" height="160" fill="#2b2140"/><rect x="110" y="0" width="110" height="160" fill="#fff3b0"/>'+DEVI(55,10,.55,False,'#111','#2b2b3a')+STARS(6,3)+'<rect x="140" y="80" width="60" height="50" fill="#fde4e4" stroke="#111"/><path d="M134 82 L170 54 L206 82z" fill="#c0392b" stroke="#111"/>'+DEVI(170,0,.35,False,'#c0392b')+T(55,150,'MAHĀMĀRĪ',9,'#fff')+T(170,150,'LAKṢMĪ',9)),
 'This whole cosmic egg, O lord of men, is pervaded by her, the Great Devī, Mahākālī, in the form of Mahāmārī. She, in time, is the Great Death; she, the unborn, becomes creation; she, the eternal, sustains beings in time. In good times she is Lakṣmī in people’s homes, giving increase; and in times of loss she becomes Alakṣmī, for their ruin. Praised and worshipped with flowers, perfumes, incense and the rest, she gives wealth and children, and a mind set well on dharma.',
 [('brahmāṇḍa','<b>the cosmic egg</b>, the universe'),('mahā-mārī','<b>the great death</b>, also great pestilence'),('ajā','<b>the unborn</b>'),('bhava-kāle','<b>in good times</b>'),('matim dharme śubhām','<b>a mind well set on dharma</b>')],
 '<b>All of it is her.</b> Death and creation, prosperity and ruin, Mahākālī and Lakṣmī. Medhas does not soften it: the same Goddess is behind both. And her last gift in the list is not wealth, but a good mind set on dharma.',
 'Death and birth, ruin and fortune: <b>all are her</b>.'),
]
